import bcrypt from "bcryptjs";
import crypto from "crypto";
import { Resend } from 'resend';
import { storage } from "./storage";
import type { Express, RequestHandler, Request, Response } from "express";
import session from "express-session";
import connectPg from "connect-pg-simple";
import { env, isDevelopment } from "./config";
import { db } from "./db";
import { users } from "@shared/schema";
import { eq } from "drizzle-orm";

// Extend Express Session interface
declare module "express-session" {
  interface SessionData {
    userId: string;
    email?: string;
  }
}

export function getSession() {
  const sessionTtl = 30 * 24 * 60 * 60 * 1000; // 30 days for better persistence
  const pgStore = connectPg(session);
  const sessionStore = new pgStore({
    conString: env.DATABASE_URL,
    createTableIfMissing: false,
    ttl: sessionTtl / 1000,
    tableName: "sessions",
  });

  return session({
    secret: env.SESSION_SECRET,
    store: sessionStore,
    resave: false,
    saveUninitialized: false,
    name: "connect.sid",
    rolling: true,
    cookie: {
      httpOnly: true,
      secure: !isDevelopment,
      maxAge: sessionTtl,
      sameSite: "none",
      path: "/",
    },
    unset: "destroy", // Ensures session is completely removed on logout
    proxy: true, // Trust first proxy for proper session handling
    genid: () => {
      return crypto.randomBytes(32).toString("hex");
    },
  });
}

export const isAuthenticated: RequestHandler = async (req: any, res, next) => {
  // Set no-cache headers for authenticated endpoints
  res.set({
    "Cache-Control": "no-cache, no-store, must-revalidate",
    Pragma: "no-cache",
    Expires: "0",
  });

  if (!req.session || !req.session.userId) {
    // Authentication check failed
    return res.status(401).json({ message: "Unauthorized" });
  }

  try {
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      console.log(
        `[AUTH-CHECK] User not found in database: ${req.session.userId}`,
      );
      req.session.destroy(() => {});
      return res.status(401).json({ message: "Unauthorized" });
    }

    // User authenticated successfully

    req.user = user;
    next();
  } catch (error) {
    console.error("Authentication error:", error);
    req.session.destroy(() => {});
    return res.status(401).json({ message: "Unauthorized" });
  }
};

export const hashPassword = async (password: string): Promise<string> => {
  return await bcrypt.hash(password, 12);
};

export const verifyPassword = async (
  password: string,
  hash: string,
): Promise<boolean> => {
  return await bcrypt.compare(password, hash);
};

export const generateToken = (): string => {
  return crypto.randomBytes(32).toString("hex");
};

export const generateUserId = (): string => {
  return crypto.randomUUID();
};

export async function setupAuth(app: Express) {
  app.set("trust proxy", 1);
  app.use(getSession());

  // Login route
  app.post("/api/auth/login", async (req, res) => {
    const { email, password } = req.body;

    if (!email || !password) {
      return res
        .status(400)
        .json({ message: "Email and password are required" });
    }

    try {
      const user = await loginUser(email, password);

      // Store user session
      req.session.userId = user.id;

      // Session created

      res.json({
        message: "Login successful",
        user: {
          id: user.id,
          email: user.email,
          firstName: user.firstName,
          lastName: user.lastName,
          isEmailConfirmed: user.isEmailConfirmed,
        },
      });
    } catch (error: any) {
      console.error("Login error:", error.message);
      res.status(401).json({ message: error.message });
    }
  });

  app.post("/api/auth/biometric-login", async (req: any, res: any) => {
    const { email, biometricData } = req.body;

    if (!email || !biometricData) {
      return res
        .status(400)
        .json({ message: "Email and biometric data required" });
    }

    // Validate biometric data structure
    if (!biometricData.id || !biometricData.type) {
      return res.status(400).json({ message: "Invalid biometric data format" });
    }

    try {
      // Verify the user exists and is confirmed
      const userRows = await db
        .select()
        .from(users)
        .where(eq(users.email, email))
        .execute();

      if (userRows.length === 0) {
        return res
          .status(401)
          .json({ message: "Invalid credentials or email not confirmed" });
      }

      const user = userRows[0];

      // Check if user's email is confirmed
      if (!user.isEmailConfirmed) {
        return res.status(401).json({
          message: "Email not confirmed. Please verify your email first.",
        });
      }

      // In a real implementation, you would:
      // 1. Verify the biometric assertion against stored public key
      // 2. Validate the signature
      // 3. Check the authenticator data
      // For now, we'll verify basic biometric data presence and user existence

      // Store user session
      req.session.userId = user.id;
      req.session.email = user.email;

      // Session created

      res.json({
        message: "Biometric login successful",
        user: {
          id: user.id,
          email: user.email,
          firstName: user.firstName,
          lastName: user.lastName,
          isEmailConfirmed: user.isEmailConfirmed,
          createdAt: user.createdAt,
        },
      });
    } catch (error: any) {
      console.error("Biometric login error:", error.message);
      res.status(401).json({ message: "Biometric authentication failed" });
    }
  });
}

// Configure Resend
let resend: Resend | null = null;
console.log('Checking Resend configuration...');
console.log('RESEND_API_KEY exists:', !!env.RESEND_API_KEY);
if (env.RESEND_API_KEY) {
  console.log('Initializing Resend client...');
  resend = new Resend(env.RESEND_API_KEY);
  console.log('Resend client initialized successfully');
} else {
  console.log('RESEND_API_KEY not found in environment variables');
}

