import * as React from 'react';
import { useToast } from '@/hooks/use-toast';
import { Capacitor } from '@capacitor/core';
import { PushNotifications } from '@capacitor/push-notifications';
import { LocalNotifications } from '@capacitor/local-notifications';

interface PushNotificationOptions {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  tag?: string;
  requireInteraction?: boolean;
  silent?: boolean;
  data?: any;
}

interface UsePushNotificationsReturn {
  isSupported: boolean;
  permission: NotificationPermission | null;
  isSubscribed: boolean;
  requestPermission: () => Promise<boolean>;
  sendNotification: (options: PushNotificationOptions) => Promise<boolean>;
  scheduleNotification: (options: PushNotificationOptions, delay: number) => void;
  enableNotifications: () => Promise<boolean>;
  disableNotifications: () => void;
}

export function usePushNotifications(): UsePushNotificationsReturn {
  const [isSupported, setIsSupported] = React.useState(false);
  const [permission, setPermission] = React.useState<NotificationPermission | null>(null);
  const [isSubscribed, setIsSubscribed] = React.useState(false);
  const { toast } = useToast();

  React.useEffect(() => {
    // Check if notifications are supported
    if (Capacitor.isNativePlatform()) {
      // Mobile platform - use Capacitor
      setIsSupported(true);
      initializeMobileNotifications();
    } else if ('Notification' in window && 'serviceWorker' in navigator) {
      // Web platform - use web notifications
      setIsSupported(true);
      setPermission(Notification.permission);
      setIsSubscribed(Notification.permission === 'granted');
    }
  }, []);

  const initializeMobileNotifications = React.useCallback(async () => {
    try {
      const pushPermissions = await PushNotifications.checkPermissions();
      const localPermissions = await LocalNotifications.checkPermissions();

      setPermission(pushPermissions.receive as NotificationPermission);
      setIsSubscribed(pushPermissions.receive === 'granted' && localPermissions.display === 'granted');

      // Add mobile event listeners
      PushNotifications.addListener('pushNotificationActionPerformed', (notification) => {
        if (notification.notification.data?.type === 'reminder') {
          window.location.href = '/schedule';
        }
      });

      LocalNotifications.addListener('localNotificationActionPerformed', (notification) => {
        if (notification.notification.extra?.type === 'reminder') {
          window.location.href = '/schedule';
        }
      });
    } catch (error) {
      console.error('Error initializing mobile notifications:', error);
    }
  }, []);

  const requestPermission = React.useCallback(async (): Promise<boolean> => {
    if (!isSupported) {
      toast({
        title: "Notifications not supported",
        description: "Your device doesn't support push notifications.",
        variant: "destructive",
      });
      return false;
    }

    try {
      if (Capacitor.isNativePlatform()) {
        // Mobile platform
        const pushPermissions = await PushNotifications.requestPermissions();
        const localPermissions = await LocalNotifications.requestPermissions();

        await PushNotifications.register();

        const granted = pushPermissions.receive === 'granted' && localPermissions.display === 'granted';
        setPermission(pushPermissions.receive as NotificationPermission);
        setIsSubscribed(granted);

        if (granted) {
          toast({
            title: "Notifications enabled",
            description: "You'll receive reminders for your pet's schedule.",
          });
        } else {
          toast({
            title: "Notifications blocked",
            description: "Please enable notifications in your device settings.",
            variant: "destructive",
          });
        }

        return granted;
      } else {
        // Web platform
        const result = await Notification.requestPermission();
        setPermission(result);
        const granted = result === 'granted';
        setIsSubscribed(granted);

        if (granted) {
          toast({
            title: "Notifications enabled",
            description: "You'll receive reminders for your pet's schedule.",
          });
        } else {
          toast({
            title: "Notifications blocked",
            description: "You can enable them in your browser settings.",
            variant: "destructive",
          });
        }

        return granted;
      }
    } catch (error) {
      console.error('Error requesting notification permission:', error);
      toast({
        title: "Permission error",
        description: "Failed to request notification permission.",
        variant: "destructive",
      });
      return false;
    }
  }, [isSupported, toast]);

  const sendNotification = React.useCallback(async (options: PushNotificationOptions): Promise<boolean> => {
    if (!isSupported || permission !== 'granted') {
      console.log('Notifications not available or not permitted');
      return false;
    }

    try {
      if (Capacitor.isNativePlatform()) {
        // Mobile platform - use local notifications
        await LocalNotifications.schedule({
          notifications: [{
            id: Date.now(),
            title: options.title,
            body: options.body,
            extra: options.data || {},
            schedule: { at: new Date(Date.now() + 1000) }, // Schedule 1 second from now
          }]
        });
      } else {
        // Web platform - use web notifications
        const notification = new Notification(options.title, {
          body: options.body,
          icon: options.icon || '/icon-192x192.png',
          badge: options.badge || '/icon-192x192.png',
          tag: options.tag || 'asopets-reminder',
          requireInteraction: options.requireInteraction || false,
          silent: options.silent || false,
          data: options.data,
        });

        // Handle notification click
        notification.onclick = (event) => {
          event.preventDefault();
          window.focus();

          // Navigate to schedule page if data contains reminder info
          if (options.data?.type === 'reminder') {
            window.location.href = '/schedule';
          }

          notification.close();
        };

        // Auto-close after 10 seconds unless requireInteraction is true
        if (!options.requireInteraction) {
          setTimeout(() => {
            notification.close();
          }, 10000);
        }
      }

      console.log('Push notification sent:', options.title);
      return true;
    } catch (error) {
      console.error('Error sending notification:', error);
      return false;
    }
  }, [isSupported, permission]);

  const scheduleNotification = React.useCallback(async (options: PushNotificationOptions, delay: number) => {
    if (!isSupported || permission !== 'granted') {
      console.log('Cannot schedule notification - not supported or not permitted');
      return;
    }

    try {
      if (Capacitor.isNativePlatform()) {
        // Mobile platform - use local notifications with proper scheduling
        const scheduleDate = new Date(Date.now() + delay);

        await LocalNotifications.schedule({
          notifications: [{
            id: Date.now(),
            title: options.title,
            body: options.body,
            extra: options.data || {},
            schedule: { at: scheduleDate },
          }]
        });

        console.log(`Mobile notification scheduled for ${scheduleDate.toISOString()}:`, options.title);
      } else {
        // Web platform - use setTimeout
        setTimeout(() => {
          sendNotification(options);
        }, delay);

        console.log(`Web notification scheduled for ${delay}ms from now:`, options.title);
      }
    } catch (error) {
      console.error('Error scheduling notification:', error);
    }
  }, [isSupported, permission, sendNotification]);

  const enableNotifications = React.useCallback(async (): Promise<boolean> => {
    if (permission === 'granted') {
      setIsSubscribed(true);
      return true;
    }

    return await requestPermission();
  }, [permission, requestPermission]);

  const disableNotifications = React.useCallback(() => {
    setIsSubscribed(false);
    toast({
      title: "Notifications disabled",
      description: "You won't receive push notifications for reminders.",
    });
  }, [toast]);

  return {
    isSupported,
    permission,
    isSubscribed,
    requestPermission,
    sendNotification,
    scheduleNotification,
    enableNotifications,
    disableNotifications,
  };
}

// Utility functions for pet-specific notifications
export const createReminderNotification = (
  petName: string,
  reminderTitle: string,
  reminderType: string,
  dueDate: string
): PushNotificationOptions => {
  const petEmoji = {
    dog: '🐕',
    cat: '🐱',
    rabbit: '🐰',
    bird: '🐦',
    horse: '🐴',
    exotic: '🦎',
    other: '🐾'
  };

  const typeEmoji = {
    vaccine: '💉',
    deworming: '💊',
    treatment: '🏥',
    surgery: '⚕️',
    checkup: '🩺',
    grooming: '✂️'
  };

  return {
    title: `${petEmoji[petName as keyof typeof petEmoji] || '🐾'} ${petName} Reminder`,
    body: `${typeEmoji[reminderType as keyof typeof typeEmoji] || '📅'} ${reminderTitle} is due ${dueDate}`,
    icon: '/icon-192x192.png',
    badge: '/icon-192x192.png',
    tag: `reminder-${petName}-${reminderType}`,
    requireInteraction: true,
    data: {
      type: 'reminder',
      petName,
      reminderTitle,
      reminderType,
      dueDate
    }
  };
};

export const createOverdueNotification = (
  petName: string,
  reminderTitle: string,
  reminderType: string,
  daysOverdue: number
): PushNotificationOptions => {
  return {
    title: `⚠️ ${petName} - Overdue Reminder`,
    body: `${reminderTitle} is ${daysOverdue} day${daysOverdue > 1 ? 's' : ''} overdue`,
    icon: '/icon-192x192.png',
    badge: '/icon-192x192.png',
    tag: `overdue-${petName}-${reminderType}`,
    requireInteraction: true,
    data: {
      type: 'overdue',
      petName,
      reminderTitle,
      reminderType,
      daysOverdue
    }
  };
};

client/src/hooks/use-toast.ts.content:
import * as React from "react"
import type { ReactNode } from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: ReactNode
  description?: ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

