    if (savedDraft) {
      try {
        const draftData = JSON.parse(savedDraft);
        form.reset(draftData);
      } catch (error) {
        console.error("Failed to load draft:", error);
      }
    }
  }, [form]);

  const handleFileSelect = async (file: File) => {
    if (!file.type.startsWith("image/")) {
      toast({
        title: "Error",
        description: "Please select an image file",
        variant: "destructive",
      });
      return;
    }

    // Check file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      toast({
        title: "Error",
        description: "Image size should be less than 10MB",
        variant: "destructive",
      });
      return;
    }

    setIsUploading(true);

    try {
      // Create a promise-based image processing function
      const processImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");

          if (!ctx) {
            reject(new Error("Canvas context not available"));
            return;
          }

          const img = document.createElement("img");

          img.onload = () => {
            try {
              // Calculate new dimensions (max 800px width/height)
              const maxSize = 800;
              let { width, height } = img;

              if (width > height && width > maxSize) {
                height = (height * maxSize) / width;
                width = maxSize;
              } else if (height > maxSize) {
                width = (width * maxSize) / height;
                height = maxSize;
              }

              canvas.width = width;
              canvas.height = height;

              ctx.drawImage(img, 0, 0, width, height);

              // Convert to compressed JPEG
              const compressedDataUrl = canvas.toDataURL("image/jpeg", 0.8);

              // Clean up the object URL
              URL.revokeObjectURL(img.src);

              resolve(compressedDataUrl);
            } catch (error) {
              reject(error);
            }
          };

          img.onerror = () => {
            URL.revokeObjectURL(img.src);
            reject(new Error("Failed to load image"));
          };

          img.src = URL.createObjectURL(file);
        });
      };

      // Process the image
      const compressedDataUrl = await processImage(file);
      setSelectedImage(compressedDataUrl);
      form.setValue("imageUrl", compressedDataUrl);

      toast({
        title: "Success",
        description: "Image uploaded successfully",
      });

    } catch (error) {
      console.error("Image processing error:", error);
      toast({
        title: "Error",
        description: `Failed to process image: ${error instanceof Error ? error.message : "Unknown error"}`,
        variant: "destructive",
      });
    } finally {
      setIsUploading(false);
    }
  };

  const handleCameraCapture = () => {
    if (cameraInputRef.current) {
      cameraInputRef.current.click();
    }
  };

  const handleFileUpload = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const removeSelectedImage = () => {
    setSelectedImage(null);
    form.setValue("imageUrl", "");
    if (fileInputRef.current) fileInputRef.current.value = "";
    if (cameraInputRef.current) cameraInputRef.current.value = "";
  };

  const createPetMutation = useMutation({
    mutationFn: async (data: Omit<InsertPet, "userId">) => {
      await apiRequest("POST", "/api/pets", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/pets"] });
      toast({
        title: "Success",
        description: "Pet profile created successfully!",
      });
      setLocation("/");
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: Omit<InsertPet, "userId">) => {
    if (!selectedCategory) {
      toast({
        title: "Error",
        description: "Please select a pet category",
        variant: "destructive",
      });
      return;
    }

    // Validate birth date is not in the future
    if (data.dateOfBirth && new Date(data.dateOfBirth) > new Date()) {
      toast({
        title: "Error",
        description: "Birth date cannot be in the future",
        variant: "destructive",
      });
      return;
    }

    createPetMutation.mutate({
      ...data,
      category: selectedCategory,
    });
  };

  return (
    <div className="mobile-container">
      {/* Header */}
      <div className="bg-primary text-white p-4">
        <div className="flex items-center">
          <button onClick={() => setLocation("/")} className="mr-4">
            <ArrowLeft className="w-6 h-6" />
          </button>
          <div className="flex-1">
            <h2 className="text-xl font-bold">Add New Pet</h2>
            <p className="text-white/80 text-sm">
              Create a complete profile for your pet
            </p>
          </div>
        </div>
      </div>

      <div className="p-4 space-y-6">
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            {/* Pet Category Selection */}
            <div>
              <Label className="block text-sm font-medium text-gray-700 mb-3">
                Pet Category
              </Label>
              <div className="grid grid-cols-3 gap-3">
                {petCategories.map(({ value, label, icon: Icon }) => (
                  <button
                    key={value}
                    type="button"
                    className={`pet-category-btn ${selectedCategory === value ? "selected" : ""}`}
                    onClick={() => {
                      setSelectedCategory(value);
                      form.setValue("category", value);
                    }}
                  >
                    <Icon className="w-6 h-6 text-gray-600 mb-2" />
                    <span className="text-sm font-medium">{label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Pet Photo Upload */}
            <div>
              <Label className="block text-sm font-medium text-gray-700 mb-3">
                Pet Photo
              </Label>

              {/* Hidden file inputs */}
              <input
                ref={cameraInputRef}
                type="file"
                accept="image/*"
                capture="environment"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) handleFileSelect(file);
                }}
                className="hidden"
              />
              <input
                ref={fileInputRef}
