                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="microchipId"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Microchip ID (Optional)</FormLabel>
                    <FormControl>
                      <Input
                        placeholder="Enter microchip ID"
                        {...field}
                        value={field.value || ""}
