import { useState, useEffect, useRef, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { isUnauthorizedError } from "@/lib/authUtils";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Bell, Plus, Calendar, Syringe, BarChart3, MapPin, QrCode, Trash2, Upload } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { PageLoader } from "@/components/loading-spinner";
import PetCard from "@/components/pet-card";
import DashboardInsights from "@/components/dashboard-insights";
import OfflineSyncIndicator from "@/components/offline-sync-indicator";
import BottomNavigation from "@/components/bottom-navigation";
import QuickActions from "@/components/quick-actions";
import VetClinics from "@/components/vet-clinics";
import QRScanner from "@/components/qr-scanner";
import ScannedPetViewer from "@/components/scanned-pet-viewer";
import ScannedPetTransfer from "@/components/scanned-pet-transfer";
import { apiRequest } from "@/lib/queryClient";
import MedicationReminderManager from "@/components/medication-reminder-manager";
import PullToRefresh from "@/components/pull-to-refresh";
import type { Pet, Reminder, MedicalRecord } from "@shared/schema";

export default function Dashboard() {
  const { user, isLoading, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const [, setLocation] = useLocation();
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState("overview");
  const [showVetClinics, setShowVetClinics] = useState(false);
  const [showQRScanner, setShowQRScanner] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [scannedPetData, setScannedPetData] = useState<any>(null);
  const [showTransferDialog, setShowTransferDialog] = useState(false);
  const [transferPetData, setTransferPetData] = useState<any>(null);

  const [petToDelete, setPetToDelete] = useState<Pet | null>(null);

  // Pull to refresh handler
  const handleRefresh = useCallback(async () => {
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: ["/api/pets"] }),
      queryClient.invalidateQueries({ queryKey: ["/api/reminders"] }),
      queryClient.invalidateQueries({ queryKey: ["/api/reminders/overdue"] }),
      queryClient.invalidateQueries({ queryKey: ["/api/scanned-pets"] }),
      queryClient.invalidateQueries({ queryKey: ["/api/medical-records/all"] }),
    ]);
  }, [queryClient]);

  // Remove localStorage scanned pets logic since we're using database now

  // Redirect to login if not authenticated
  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      toast({
        title: "Unauthorized",
        description: "You are logged out. Logging in again...",
        variant: "destructive",
      });
      setTimeout(() => {
        window.location.href = "/api/login";
      }, 500);
      return;
    }
  }, [isAuthenticated, isLoading, toast]);

  const { data: pets = [], isLoading: petsLoading } = useQuery<Pet[]>({
    queryKey: ["/api/pets"],
    queryFn: async () => {
      const response = await fetch("/api/pets?includePhotos=true&limit=20");
      if (!response.ok) throw new Error(`${response.status}: ${response.statusText}`);
      return response.json();
    },
    enabled: !!user,
  });

  const { data: reminders = [] } = useQuery<Reminder[]>({
    queryKey: ["/api/reminders"],
    enabled: !!user,
  });

  const { data: overdueReminders = [] } = useQuery<Reminder[]>({
    queryKey: ["/api/reminders/overdue"],
    enabled: !!user,
  });

  // Fetch scanned pets from database
  const { data: scannedPets = [] } = useQuery<any[]>({
    queryKey: ["/api/scanned-pets"],
    enabled: !!user,
  });

  // Fetch all medical records for insights
  const allMedicalRecordsQueries = useQuery({
    queryKey: ["/api/medical-records/all"],
    queryFn: async () => {
      const allRecords: MedicalRecord[] = [];
      for (const pet of pets) {
        const response = await fetch(`/api/pets/${pet.id}/medical-records`);
        if (response.ok) {
          const records = await response.json();
          allRecords.push(...records);
        }
      }
      return allRecords;
    },
    enabled: !!user && pets.length > 0,
  });

  const allMedicalRecords = allMedicalRecordsQueries.data || [];

  // Create scanned pet mutation
  const createScannedPetMutation = useMutation({
    mutationFn: async (scannedPetData: any) => {
      return await apiRequest("POST", "/api/scanned-pets", scannedPetData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/scanned-pets"] });
    },
  });

  // Delete scanned pet mutation
  const deleteScannedPetMutation = useMutation({
    mutationFn: async (petId: string) => {
      return await apiRequest("DELETE", `/api/scanned-pets/by-pet/${petId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/scanned-pets"] });
    },
  });

  // Delete pet mutation
  const deletePetMutation = useMutation({
    mutationFn: async (petId: number) => {
      const response = await fetch(`/api/pets/${petId}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      if (!response.ok) {
        throw new Error('Failed to delete pet');
      }
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Pet Deleted",
        description: "Pet and all associated records have been permanently deleted.",
      });
      // Invalidate and refetch pets data
      queryClient.invalidateQueries({ queryKey: ['/api/pets'] });
      queryClient.invalidateQueries({ queryKey: ['/api/reminders'] });
      setPetToDelete(null);
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: "Failed to delete pet. Please try again.",
        variant: "destructive",
      });
    },
  });

  if (isLoading || petsLoading) {
    return <PageLoader />;
  }

  const totalNotifications = overdueReminders.length;

  return (
    <div className="mobile-container mobile-safe touch-manipulation">
      {/* Header */}
      <div className="bg-primary text-white p-4 safe-area-top">
        <div className="flex items-center justify-between mt-[0px] mb-[0px] pt-[10px] pb-[10px]">
          <div>
            <h1 className="text-xl font-bold pt-[0px] pb-[0px] mt-[0px] mb-[0px]">Welcome back!</h1>
            <p className="text-white/80 text-sm">
              Managing {pets.length} pet{pets.length !== 1 ? "s" : ""}
            </p>
          </div>
          <div className="flex items-center space-x-3">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowNotifications(true)}
              onTouchStart={(e) => e.currentTarget.style.transform = 'scale(0.95)'}
              onTouchEnd={(e) => e.currentTarget.style.transform = 'scale(1)'}
              className="relative text-[#333333] touch-manipulation"
            >
              <Bell className="w-4 h-4" />
              {totalNotifications > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs w-5 h-5 rounded-full flex items-center justify-center">
                  {totalNotifications > 9 ? '9+' : totalNotifications}
                </span>
              )}
            </Button>
          </div>
        </div>
      </div>
      {/* Content */}
      <PullToRefresh onRefresh={handleRefresh} className="flex-1">
        <div className="p-4 pb-20">
        {/* Offline Sync Indicator */}
        <OfflineSyncIndicator />

        <Tabs defaultValue="pets" className="w-full">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="pets">My Pets</TabsTrigger>
            <TabsTrigger value="insights">Health Insights</TabsTrigger>
          </TabsList>
          {/* Overdue Reminders Alert */}
          {overdueReminders.length > 0 && (
            <Card className="border-destructive bg-red-50">
              <CardContent className="p-4">
                <div className="flex items-center mb-3">
                  <Bell className="text-destructive mr-2 w-5 h-5" />
                  <h3 className="font-semibold text-gray-900">
                    Overdue Reminders
                  </h3>
                </div>
                <div className="space-y-2">
                  {overdueReminders.slice(0, 3).map((reminder) => (
                    <div
                      key={reminder.id}
                      className="flex justify-between items-center"
                    >
                      <span className="text-sm text-gray-700">
                        {reminder.title}
                      </span>
                      <span className="status-badge overdue">Overdue</span>
                    </div>
                  ))}
                  {overdueReminders.length > 3 && (
                    <p className="text-xs text-gray-500">
                      +{overdueReminders.length - 3} more overdue items
                    </p>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          <TabsContent value="pets" className="space-y-6 mt-6">
            <div className="flex items-center">
              <h2 className="text-lg font-semibold text-gray-900">Your Pets</h2>
            </div>
            {/* Pet Grid */}
            <div className="grid grid-cols-2 gap-4">
              {pets.map((pet) => (
                <PetCard
                  key={pet.id}
                  pet={pet}
                  reminders={reminders.filter((r) => r.petId === pet.id)}
                  onDelete={(pet) => setPetToDelete(pet)}
                />
              ))}
              {/* Add Pet Card */}
              <div
                className="bg-gray-50 p-4 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center cursor-pointer hover:border-primary transition-colors touch-manipulation active:scale-95"
                onClick={() => setLocation("/add-pet")}
                onTouchStart={(e) => e.currentTarget.style.transform = 'scale(0.95)'}
                onTouchEnd={(e) => e.currentTarget.style.transform = 'scale(1)'}
              >
                <Plus className="text-gray-400 text-2xl mb-2" />
                <p className="text-gray-500 text-sm font-medium">Add Pet</p>
              </div>

              {/* Bulk Add Pets Card */}
              <div
                className="bg-green-50 p-4 rounded-xl border-2 border-dashed border-green-300 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-colors touch-manipulation active:scale-95"
                onClick={() => setLocation("/bulk-add-pets")}
                onTouchStart={(e) => e.currentTarget.style.transform = 'scale(0.95)'}
                onTouchEnd={(e) => e.currentTarget.style.transform = 'scale(1)'}
              >
                <Upload className="text-green-400 text-2xl mb-2" />
                <p className="text-green-500 text-sm font-medium">Bulk Import</p>
              </div>
              {/* QR Scanner Card */}
              <div
                className="bg-blue-50 p-4 rounded-xl border-2 border-dashed border-blue-300 flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-colors touch-manipulation active:scale-95"
                onClick={() => setShowQRScanner(true)}
                onTouchStart={(e) => e.currentTarget.style.transform = 'scale(0.95)'}
                onTouchEnd={(e) => e.currentTarget.style.transform = 'scale(1)'}
              >
                <QrCode className="text-blue-400 text-2xl mb-2" />
                <p className="text-blue-500 text-sm font-medium">Scan Pet QR</p>
              </div>
            </div>

            {/* Other Pets Section - Scanned QR Codes */}
            {scannedPets.length > 0 && (
              <>
                <div className="flex items-center justify-between mt-8">
                  <h2 className="text-lg font-semibold text-gray-900">Other Pets</h2>
                  <span className="text-sm text-gray-500">{scannedPets.length} scanned</span>
                </div>
                <div className="grid grid-cols-1 gap-4">
                  {scannedPets.map((pet, index) => (
                    <Card 
                      key={pet.petId || index} 
                      className="cursor-pointer hover:shadow-md transition-shadow touch-manipulation active:scale-98"
                      onClick={() => {
                        console.log("Opening scanned pet viewer for:", pet);
                        setScannedPetData(pet);
                      }}
                      onTouchStart={(e) => e.currentTarget.style.transform = 'scale(0.98)'}
                      onTouchEnd={(e) => e.currentTarget.style.transform = 'scale(1)'}
                    >
                      <CardContent className="p-4">
                        <div className="flex items-start space-x-3">
                          <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
                            <span className="text-lg">🐾</span>
                          </div>
                          <div className="flex-1">
                            <h3 className="font-medium text-gray-900">{pet.petName || pet.name}</h3>
                            <p className="text-sm text-gray-600">{pet.breed}</p>
                            {pet.owner && (
                              <p className="text-xs text-gray-500 mt-1">
                                Owner: {pet.owner.name}
                              </p>
                            )}
                            <p className="text-xs text-gray-400 mt-1">
                              Scanned: {pet.scannedAt ? new Date(pet.scannedAt).toLocaleDateString() : 'Unknown date'}
                            </p>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </>
            )}

            {/* Quick Actions - moved below Other Pets */}
            <QuickActions onFindClinics={() => setShowVetClinics(true)} />
          </TabsContent>

          <TabsContent value="insights" className="mt-6">
            <DashboardInsights
              pets={pets}
              allMedicalRecords={allMedicalRecords}
              reminders={reminders}
            />
          </TabsContent>
        </Tabs>
        </div>
      </PullToRefresh>

      {/* Find Vet Clinics Modal */}
      {showVetClinics && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-start justify-center pt-10">
          <div className="bg-white rounded-lg m-4 max-w-lg w-full max-h-[80vh] overflow-y-auto">
            <div className="p-4 border-b flex items-center justify-between">
              <h2 className="text-lg font-semibold">Find Vet Clinics</h2>
              <button
                onClick={() => setShowVetClinics(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                ×
              </button>
            </div>
            <div className="p-4">
              <VetClinics />
            </div>
          </div>
        </div>
      )}
      {showQRScanner && (
        <QRScanner 
          onClose={() => setShowQRScanner(false)}
          onScanSuccess={(data) => {
            console.log("QR Scanner - Raw scanned data:", data);
            setShowQRScanner(false);

            if (data && data.type === "pet_profile" && data.petId) {
              // Check if pet is already scanned
              const exists = scannedPets.some(pet => pet.petId === data.petId);
              if (!exists) {
                // Prepare scanned pet data for database
                const scannedPetData = {
                  petId: data.petId,
                  ownerId: data.ownerId,
                  type: data.type,
                  name: data.name,
                  petName: data.petName,
                  category: data.category,
                  breed: data.breed,
                  dateOfBirth: data.dateOfBirth,
                  age: data.age,
                  imageUrl: data.imageUrl,
                  microchipId: data.microchipId,
                  birthmarks: data.birthmarks,
                  medicalRecordCount: data.medicalRecordCount,
                  lastUpdated: data.lastUpdated,
                  ownerName: data.owner?.name,
                  ownerPhone: data.owner?.phone,
                  ownerEmail: data.owner?.email,
                  emergencyContact: data.owner?.emergencyContact,
                  emergencyPhone: data.owner?.emergencyPhone,
                };

                console.log("Adding new scanned pet to database:", scannedPetData);
                createScannedPetMutation.mutate(scannedPetData);

                toast({
                  title: "Pet Profile Scanned",
                  description: `Added ${data.name || data.petName || 'pet'} to Other Pets section`,
                });
              } else {
                toast({
                  title: "Pet Already Scanned",
                  description: `${data.name || data.petName || 'Pet'} is already in your Other Pets list`,
                });
              }
            } else {
              console.error("Invalid QR data received:", data);
              toast({
                title: "Invalid QR Code",
                description: "This QR code is not a valid pet profile",
                variant: "destructive",
              });
            }
          }}
        />
      )}
      {scannedPetData && (
        <ScannedPetViewer 
          data={scannedPetData}
          onClose={() => setScannedPetData(null)}
          onDelete={(petData) => {
            console.log("Deleting scanned pet:", petData.petId);
            deleteScannedPetMutation.mutate(petData.petId);
            setScannedPetData(null);

            toast({
              title: "Pet Removed",
              description: "Scanned pet has been removed from your list.",
            });
          }}
          onTransfer={async (petData) => {
            try {
              const newPetData = {
                name: petData.name || petData.petName || 'Transferred Pet',
                category: petData.category || 'other',
                breed: petData.breed || '',
                dateOfBirth: petData.dateOfBirth || new Date().toISOString().split('T')[0],
                age: petData.age || 0,
                microchipId: petData.microchipId || '',
                birthmarks: petData.birthmarks || '',
                imageUrl: petData.imageUrl || ''
              };

              console.log('Transferring pet data:', newPetData);

              await apiRequest("POST", "/api/pets", newPetData);
              queryClient.invalidateQueries({ queryKey: ["/api/pets"] });

              // Delete from scanned pets after successful transfer
              deleteScannedPetMutation.mutate(petData.petId);
              setScannedPetData(null);

              toast({
                title: "Pet Added Successfully!",
                description: `${newPetData.name} has been added to your pets.`,
              });
            } catch (error: any) {
              console.error('Transfer pet error:', error);
              toast({
                title: "Transfer Failed",
                description: error.message || "Failed to add pet to your profile.",
                variant: "destructive",
              });
            }
          }}
        />
      )}
      <MedicationReminderManager 
        showDropdown={showNotifications}
        onDropdownClose={() => setShowNotifications(false)}
      />
      {/* Delete Pet Confirmation Dialog */}
      {petToDelete && (
        <AlertDialog open={true} onOpenChange={() => setPetToDelete(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete Pet Profile</AlertDialogTitle>
              <AlertDialogDescription>
                Are you sure you want to delete {petToDelete.name}'s profile? This will permanently remove:
                <ul className="mt-2 list-disc list-inside space-y-1">
                  <li>Pet profile and information</li>
                  <li>All medical records</li>
                  <li>All reminders and notifications</li>
                  <li>All photos and attachments</li>
                </ul>
                <p className="mt-2 font-medium text-red-600">This action cannot be undone.</p>
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={() => setPetToDelete(null)}>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => {
                  deletePetMutation.mutate(petToDelete.id);
                }}
                className="bg-red-600 hover:bg-red-700"
                disabled={deletePetMutation.isPending}
              >
                {deletePetMutation.isPending ? 'Deleting...' : 'Delete Pet'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}

      <BottomNavigation activeTab="home" />
    </div>
  );
}

