const categories = [...new Set(faqData.map(item => item.category))];

export default function FAQ() {
  const [, setLocation] = useLocation();
  const [openItems, setOpenItems] = useState<string[]>([]);

  const toggleItem = (question: string) => {
    setOpenItems(prev => 
      prev.includes(question) 
        ? prev.filter(item => item !== question)
        : [...prev, question]
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-4xl mx-auto px-4">
        <div className="mb-6">
          <Button 
            onClick={() => setLocation("/")} 
            variant="ghost" 
            className="mb-4"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Dashboard
          </Button>
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center text-2xl">
              <HelpCircle className="w-6 h-6 mr-3 text-blue-600" />
              Frequently Asked Questions
            </CardTitle>
            <p className="text-gray-600 mt-2">
              Find answers to common questions about ASOPETS
            </p>
          </CardHeader>
          <CardContent className="space-y-6">
            {categories.map((category) => (
              <div key={category}>
                <h3 className="text-lg font-semibold mb-4 text-gray-900 border-b pb-2">
                  {category}
                </h3>
                <div className="space-y-3">
                  {faqData
                    .filter(item => item.category === category)
                    .map((item, index) => (
                      <Collapsible 
                        key={`${category}-${index}`}
                        open={openItems.includes(item.question)}
                        onOpenChange={() => toggleItem(item.question)}
                      >
                        <CollapsibleTrigger className="w-full">
                          <Card className="hover:bg-gray-50 transition-colors cursor-pointer">
                            <CardContent className="p-4">
                              <div className="flex items-center justify-between">
                                <h4 className="font-medium text-left text-gray-900">
                                  {item.question}
                                </h4>
                                {openItems.includes(item.question) ? (
                                  <ChevronDown className="w-5 h-5 text-gray-500" />
                                ) : (
                                  <ChevronRight className="w-5 h-5 text-gray-500" />
                                )}
                              </div>
                            </CardContent>
                          </Card>
                        </CollapsibleTrigger>
                        <CollapsibleContent>
                          <div className="px-4 pb-4 text-gray-700">
                            {item.answer}
                          </div>
                        </CollapsibleContent>
                      </Collapsible>
                    ))}
