              </p>
              <Button 
                onClick={() => setLocation("/profile")}
                className="bg-blue-600 hover:bg-blue-700"
              >
                Contact Support
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

