import { useState, useEffect, useRef, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  User,
  Mail,
  MapPin,
  Phone,
  Calendar,
  Edit3,
  Save,
  X,
  Camera,
  Shield,
  Key,
  Bell,
  Globe,
  Smartphone,
  LogOut,
  Trash2,
  Fingerprint,
  Download,
  Upload,
  MessageSquare,
  Send,
  Heart,
  Settings,
  Edit,
} from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import PhotoUpload from "@/components/photo-upload";
import MultiPhotoUpload from "@/components/multi-photo-upload";
import AdBanner from "@/components/ad-banner";
import BottomNavigation from "@/components/bottom-navigation";
import { useBiometric } from "@/hooks/useBiometric";
import { useAdMob } from "@/hooks/useAdMob";
import { ADMOB_CONFIG } from "@/lib/admob-config";
import { adUtils } from "@/utils/ad-utils";
import { Label } from "@/components/ui/label";
import { format } from "date-fns";
import type { User as UserType, Pet, Reminder, MedicalRecord } from "@shared/schema";

interface UserProfile {
  id: string;
  email?: string;
  firstName?: string;
  lastName?: string;
  phone?: string;
  address?: string;
  city?: string;
  country?: string;
  dateOfBirth?: string;
  emergencyContact?: string;
  emergencyPhone?: string;
  preferredLanguage?: string;
  profileImageUrl?: string;
  notificationPreferences?: {
    email: boolean;
    push: boolean;
    reminders: boolean;
  };
}

const contactSupportSchema = z.object({
  subject: z.string().min(5, "Subject must be at least 5 characters"),
  message: z.string().min(20, "Message must be at least 20 characters"),
  attachments: z.array(z.string()).max(3, "Maximum 3 attachments allowed").optional(),
});

const passwordChangeSchema = z.object({
  currentPassword: z.string().min(1, "Current password is required"),
  newPassword: z.string().min(6, "New password must be at least 6 characters"),
  confirmPassword: z.string().min(6, "Please confirm your new password"),
}).refine((data) => data.newPassword === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

type ContactSupportData = z.infer<typeof contactSupportSchema>;
type PasswordChangeData = z.infer<typeof passwordChangeSchema>;

export default function Profile() {
  const [, setLocation] = useLocation();
  const { user, isAuthenticated, logout } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { adsLoaded } = useAdMob(ADMOB_CONFIG);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [showContactForm, setShowContactForm] = useState(false);
  const [showPasswordChange, setShowPasswordChange] = useState(false);
  const [showNotificationSettings, setShowNotificationSettings] = useState(false);
  const [showPrivacySettings, setShowPrivacySettings] = useState(false);
  const [showDeleteConfirmation, setShowDeleteConfirmation] = useState(false);
  const [deleteConfirmationText, setDeleteConfirmationText] = useState("");

  const [profileData, setProfileData] = useState<UserProfile>({
    id: "",
    firstName: "",
    lastName: "",
    phone: "",
    address: "",
    city: "",
    country: "Philippines",
    dateOfBirth: "",
    emergencyContact: "",
    emergencyPhone: "",
    preferredLanguage: "en",
    profileImageUrl: "",
    notificationPreferences: {
      email: true,
      push: true,
      reminders: true,
    },
  });
  const {
    isSupported: biometricSupported,
    isEnrolled: hasBiometric,
    error: biometricError,
  } = useBiometric();

  const [biometricLoading, setBiometricLoading] = useState(false);

  // Initialize profile data when user loads
  useEffect(() => {
    if (user) {
      const userData = user as Record<string, any>;
      setProfileData({
        id: userData?.id || "",
        email: userData?.email || "",
        firstName: userData?.firstName || "",
        lastName: userData?.lastName || "",
        phone: userData?.phone || "",
        address: userData?.address || "",
        city: userData?.city || "",
        country: userData?.country || "Philippines",
        dateOfBirth: userData?.dateOfBirth || "",
        emergencyContact: userData?.emergencyContact || "",
        emergencyPhone: userData?.emergencyPhone || "",
        preferredLanguage: userData?.preferredLanguage || "en",
        profileImageUrl: userData?.profileImageUrl || "",
        notificationPreferences: userData?.notificationPreferences || {
          email: true,
          push: true,
          reminders: true,
        },
      });
    }
  }, [user]);

  const { data: pets = [] } = useQuery<Pet[]>({
    queryKey: ["/api/pets"],
    enabled: isAuthenticated,
  });

  const { data: reminders = [] } = useQuery<Reminder[]>({
    queryKey: ["/api/reminders"],
    enabled: isAuthenticated,
  });

  // Fetch all medical records for statistics
  const allMedicalRecordsQueries = useQuery({
    queryKey: ["/api/medical-records/all"],
    queryFn: async () => {
      const allRecords: MedicalRecord[] = [];
      for (const pet of pets) {
        const response = await fetch(`/api/pets/${pet.id}/medical-records`);
        if (response.ok) {
          const records = await response.json();
          allRecords.push(...records);
        }
      }
      return allRecords;
    },
    enabled: isAuthenticated && pets.length > 0,
  });

  const allMedicalRecords = allMedicalRecordsQueries.data || [];

  // Update profile mutation
  const updateProfileMutation = useMutation({
    mutationFn: async (data: Partial<UserProfile>) => {
      const response = await fetch("/api/auth/user", {
        method: "PUT",
        body: JSON.stringify(data),
        headers: { "Content-Type": "application/json" },
      });
      if (!response.ok) throw new Error("Failed to update profile");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
      setIsEditingProfile(false);
      toast({
        title: "Profile updated",
        description: "Your profile information has been saved successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Update failed",
        description: "Failed to update your profile. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Password change mutation
  const changePasswordMutation = useMutation({
    mutationFn: async (data: PasswordChangeData) => {
      const response = await fetch("/api/auth/change-password", {
        method: "POST",
        body: JSON.stringify(data),
        headers: { "Content-Type": "application/json" },
      });
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || "Failed to change password");
      }
      return response.json();
    },
    onSuccess: () => {
      setShowPasswordChange(false);
      toast({
        title: "Password changed",
        description: "Your password has been updated successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Password change failed",
        description: error.message || "Failed to change password. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Notification preferences mutation
  const updateNotificationsMutation = useMutation({
    mutationFn: async (preferences: any) => {
      const response = await fetch("/api/auth/user", {
        method: "PUT",
        body: JSON.stringify({ notificationPreferences: preferences }),
        headers: { "Content-Type": "application/json" },
      });
      if (!response.ok) throw new Error("Failed to update notifications");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
      toast({
        title: "Notifications updated",
        description: "Your notification preferences have been saved.",
      });
    },
    onError: () => {
      toast({
        title: "Update failed",
        description: "Failed to update notification preferences.",
        variant: "destructive",
      });
    },
  });

  // Calculate user statistics
  const totalRecords = allMedicalRecords.length;
  const totalReminders = reminders.length;
  const completedReminders = reminders.filter((r) => r.isCompleted).length;
  const overdueReminders = reminders.filter(
    (r) => r.isOverdue && !r.isCompleted,
  ).length;

  // Calculate total expenses
  const totalExpenses = allMedicalRecords
    .filter((record) => record.cost && !isNaN(parseFloat(record.cost)))
    .reduce((sum, record) => sum + parseFloat(record.cost!), 0);

  // Calculate account age based on user registration date
  const calculateAccountAge = () => {
    const userData = user as any;
    if (!userData?.createdAt) return "New member";

    const registrationDate = new Date(userData.createdAt);
    const now = new Date();
    const diffInMs = now.getTime() - registrationDate.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

    if (diffInDays < 30) {
      return `${diffInDays} day${diffInDays !== 1 ? "s" : ""}`;
    } else if (diffInDays < 365) {
      const months = Math.floor(diffInDays / 30);
      return `${months} month${months !== 1 ? "s" : ""}`;
    } else {
      const years = Math.floor(diffInDays / 365);
      const remainingMonths = Math.floor((diffInDays % 365) / 30);
      if (remainingMonths === 0) {
        return `${years} year${years !== 1 ? "s" : ""}`;
      } else {
        return `${years}y ${remainingMonths}m`;
      }
    }
  };

  const accountAge = calculateAccountAge();

  const handleLogout = async () => {
    toast({
      title: "Logging out",
      description: "Redirecting to login page...",
    });

    // Use the auth hook's logout function
    try {
      await logout();
    } catch (error) {
      console.error("Logout error:", error);
      // Fallback redirect if logout fails
      window.location.replace("/");
    }
  };

  const handleExportData = () => {
    const exportData = {
      pets,
      medicalRecords: allMedicalRecords,
      reminders,
      exportDate: new Date().toISOString(),
    };

    const dataStr = JSON.stringify(exportData, null, 2);
    const dataBlob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(dataBlob);

    const link = document.createElement("a");
    link.href = url;
    link.download = `pet-care-data-${format(new Date(), "yyyy-MM-dd")}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    toast({
      title: "Data exported",
      description: "Your pet care data has been downloaded.",
    });
  };

  const handleImportData = () => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".json";
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);

          // Validate the data structure
          if (!data.pets || !Array.isArray(data.pets)) {
            throw new Error("Invalid data format");
          }

          toast({
            title: "Import successful",
            description: `Found ${data.pets.length} pets, ${
              data.medicalRecords?.length || 0
            } medical records, and ${
              data.reminders?.length || 0
            } reminders.`,
          });

          // Here you would typically upload this data to your server
          console.log("Imported data:", data);
        } catch (error) {
          toast({
            title: "Import failed",
            description: "The file format is invalid or corrupted.",
            variant: "destructive",
          });
        }
      };
      reader.readAsText(file);
    };
    input.click();
  };

  const formatCurrency = (amount: number) => {
    return amount.toLocaleString("en-PH", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  const handleSaveProfile = async () => {
    try {
      // Filter out empty strings and null values
      const cleanData = Object.fromEntries(
        Object.entries({
          firstName: profileData.firstName,
          lastName: profileData.lastName,
          phone: profileData.phone,
          address: profileData.address,
          emergencyContact: profileData.emergencyContact,
          emergencyPhone: profileData.emergencyPhone,
          profileImageUrl: profileData.profileImageUrl,
        }).filter(
          ([key, value]) =>
            value !== "" && value !== null && value !== undefined,
        ),
      );

      await updateProfileMutation.mutateAsync(cleanData);
      setIsEditingProfile(false);
    } catch (error) {
      // Error is handled by the mutation's onError
    }
  };

  const handleInputChange = (field: string, value: string) => {
    setProfileData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const handleNotificationChange = (type: string, value: boolean) => {
    setProfileData((prev) => ({
      ...prev,
      notificationPreferences: {
        ...prev.notificationPreferences!,
        [type]: value,
      },
    }));
  };

  const handleSaveNotifications = async () => {
    await updateNotificationsMutation.mutateAsync(profileData.notificationPreferences);
    setShowNotificationSettings(false);
  };

  const { registerBiometric } = useBiometric();

  const handleSetupBiometric = async () => {
    if (!profileData?.id || !profileData?.email) return;
    setBiometricLoading(true);

    try {
      const credential = await registerBiometric(profileData.id, profileData.email);
      if (credential) {
        toast({
          title: "Biometric Setup Complete",
          description: "You can now use biometric authentication to login.",
        });
      }
    } catch (error: any) {
      toast({
        title: "Setup Failed",
        description: error.message || "Failed to setup biometric authentication.",
        variant: "destructive",
      });
    } finally {
      setBiometricLoading(false);
    }
  };

  const handleRemoveBiometric = async () => {
    if (!profileData?.id) return;
    setBiometricLoading(true);

    try {
      // Remove biometric data from local storage or server
      localStorage.removeItem(`biometric_${profileData.id}`);
      toast({
        title: "Biometric Removed",
        description: "Biometric authentication has been disabled for your account.",
      });
    } finally {
      setBiometricLoading(false);
    }
  };

  const deleteAccountMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("DELETE", "/api/auth/account");
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Account Deleted",
        description: "Your account and all associated data have been permanently deleted.",
      });
      localStorage.clear();
      window.location.href = "/login";
    },
    onError: (error: any) => {
      toast({
        title: "Deletion Failed",
        description: error.message || "Failed to delete account. Please try again.",
        variant: "destructive",
      });
    }
  });

  const handleDeleteAccount = () => {
    if (deleteConfirmationText !== "DELETE MY ACCOUNT") {
      toast({
        title: "Confirmation Required",
        description: "Please type 'DELETE MY ACCOUNT' exactly to confirm.",
        variant: "destructive",
      });
      return;
    }
    deleteAccountMutation.mutate();
  };

  if (!isAuthenticated) {
    return (
      <div className="mobile-container">
        <div className="flex items-center justify-center min-h-screen">
          <p className="text-gray-600">Please log in to view your profile.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 safe-container">
      <div className="max-w-md mx-auto bg-white min-h-screen relative mobile-safe-padding pl-[0px] pr-[0px]">
        {/* Header */}
      <div className="bg-primary text-white p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center">
            <User className="w-6 h-6 mr-3" />
            <div>
              <h1 className="text-xl font-bold">Profile</h1>
              <p className="text-white/80 text-sm">Account & Settings</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <Button
              variant="ghost"
              size="sm"
              className="text-white hover:bg-white/20 p-2"
              onClick={handleExportData}
            >
              <Download className="w-5 h-5" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="text-white hover:bg-white/20 p-2"
              onClick={handleLogout}
            >
              <LogOut className="w-5 h-5" />
            </Button>
          </div>
        </div>
      </div>

      <div className="p-4 space-y-6">
        {/* User Info Card */}
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <div className="relative">
                {profileData.profileImageUrl ? (
                  <img
                    src={profileData.profileImageUrl}
                    alt="Profile"
                    className="w-16 h-16 rounded-full object-cover border-2 border-primary/20"
                  />
                ) : (
                  <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center">
                    <User className="w-8 h-8 text-primary" />
                  </div>
                )}
                {isEditingProfile && (
                  <div className="absolute -bottom-1 -right-1">
                    <PhotoUpload
                      onPhotoUploaded={(url: string) =>
