interface ContactSupportFormProps {
  userEmail: string;
  userName: string;
  onSuccess: () => void;
  onCancel: () => void;
}

function ContactSupportForm({
  userEmail,
  userName,
  onSuccess,
  onCancel,
}: ContactSupportFormProps) {
  const { toast } = useToast();
  const form = useForm<ContactSupportData>({
    resolver: zodResolver(contactSupportSchema),
    defaultValues: {
      subject: "",
      message: "",
      attachments: [],
    },
  });

  const submitSupportRequest = useMutation({
    mutationFn: async (data: ContactSupportData) => {
      await apiRequest("POST", "/api/support/contact", {
        ...data,
        userEmail,
        userName,
      });
    },
    onSuccess: () => {
      form.reset();
      onSuccess();
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: "Failed to send support request. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: ContactSupportData) => {
    submitSupportRequest.mutate(data);
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        <FormField
          control={form.control}
          name="subject"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Subject</FormLabel>
              <FormControl>
                <Input
                  placeholder="Brief description of your issue"
                  {...field}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="message"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Message</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="Please describe your issue in detail. Include any error messages or steps you've taken."
                  rows={5}
                  {...field}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="attachments"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Attachments (Optional)</FormLabel>
              <FormControl>
                <MultiPhotoUpload
                  onPhotosUploaded={(photos) => {
                    form.setValue("attachments", photos);
                  }}
                  currentPhotos={field.value || []}
                  maxPhotos={3}
                  className="w-full"
                />
              </FormControl>
              <FormMessage />
              <p className="text-sm text-gray-500 mt-1">
                Upload up to 3 images (max 10MB each) to help us understand your issue better.
              </p>
            </FormItem>
          )}
        />

        <div className="flex space-x-2">
          <Button
            type="submit"
            disabled={submitSupportRequest.isPending}
            className="flex-1"
          >
            {submitSupportRequest.isPending ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                Sending...
              </>
            ) : (
              <>
                <Send className="w-4 h-4 mr-2" />
                Send Message
              </>
            )}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={submitSupportRequest.isPending}
          >
            Cancel
          </Button>
        </div>
      </form>
    </Form>
  );
}

interface PasswordChangeFormProps {
